<?php require_once '../../includes/functions.php'; requireLogin(); global $pdo; $employees = $pdo->query("SELECT id, first_name, last_name FROM erp_employees WHERE status = 'active' ORDER BY first_name")->fetchAll(); ?>
<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>Request Leave - ERP</title><link rel="stylesheet" href="../../assets/css/style.css?v=<?= time() ?>"><style>* { margin: 0; padding: 0; box-sizing: border-box; } body { background: #f5f5f5; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Arial, sans-serif; } .header { background: #fff; border-bottom: 1px solid #e0e0e0; padding: 16px 24px; display: flex; justify-content: space-between; align-items: center; } .header h1 { font-size: 1.5rem; font-weight: 500; } .container { max-width: 600px; margin: 24px auto; padding: 0 24px; } .card { background: white; border-radius: 8px; border: 1px solid #e0e0e0; overflow: hidden; } .card-body { padding: 24px; } .form-group { margin-bottom: 16px; } label { display: block; margin-bottom: 8px; font-weight: 500; color: #202124; font-size: 0.875rem; } input, select, textarea { width: 100%; padding: 10px 12px; border: 1px solid #dadce0; border-radius: 4px; font-size: 0.875rem; } .btn { padding: 10px 24px; border-radius: 4px; text-decoration: none; font-size: 0.875rem; font-weight: 500; cursor: pointer; border: none; } .btn-primary { background: #1a73e8; color: white; } .btn-secondary { background: #fff; color: #202124; border: 1px solid #dadce0; } .alert { padding: 12px 16px; border-radius: 4px; margin-bottom: 20px; display: none; } .alert-success { background: #e6f4ea; color: #137333; } .alert-error { background: #fce8e6; color: #c5221f; }</style></head>
<body><div class="header"><h1>Request Leave</h1><a href="leave.php" class="btn btn-secondary">Cancel</a></div><div class="container"><div class="card"><div class="card-body"><div id="alertMessage" class="alert"></div><form id="requestLeaveForm"><div class="form-group"><label>Employee *</label><select name="employee_id" required><option value="">Select Employee</option><?php foreach ($employees as $emp): ?><option value="<?= $emp['id'] ?>"><?= htmlspecialchars($emp['first_name'] . ' ' . $emp['last_name']) ?></option><?php endforeach; ?></select></div><div class="form-group"><label>Leave Type *</label><select name="leave_type" required><option value="annual">Annual Leave</option><option value="sick">Sick Leave</option><option value="unpaid">Unpaid Leave</option><option value="maternity">Maternity Leave</option><option value="paternity">Paternity Leave</option><option value="other">Other</option></select></div><div class="form-group"><label>Start Date *</label><input type="date" name="start_date" required></div><div class="form-group"><label>End Date *</label><input type="date" name="end_date" required></div><div class="form-group"><label>Reason</label><textarea name="reason" rows="3" placeholder="Optional reason for leave"></textarea></div><div style="margin-top: 24px; text-align: right;"><button type="submit" class="btn btn-primary">Submit Request</button></div></form></div></div></div><script>document.getElementById('requestLeaveForm').addEventListener('submit', async function(e) { e.preventDefault(); const btn = this.querySelector('button[type="submit"]'); btn.disabled = true; btn.textContent = 'Submitting...'; const alert = document.getElementById('alertMessage'); alert.style.display = 'none'; try { const formData = new FormData(this); formData.append('action', 'create'); const response = await fetch('../api/leave.php', { method: 'POST', body: formData }); const result = await response.json(); if (result.success) { alert.className = 'alert alert-success'; alert.textContent = 'Leave request submitted successfully! Redirecting...'; alert.style.display = 'block'; setTimeout(() => window.location.href = 'leave.php', 1500); } else { throw new Error(result.message || 'Failed to submit request'); } } catch (error) { alert.className = 'alert alert-error'; alert.textContent = error.message; alert.style.display = 'block'; btn.disabled = false; btn.textContent = 'Submit Request'; } });</script></body>
</html>

